#include <bits/stdc++.h>
int main(int c, char** v) { std::mt19937 r(atoi(v[1])); int n = r() % 8 + 2; std::set<std::pair<int,int>> e; for (int i = 2; i <= n; i++) e.insert({int(r() % (i - 1) + 1), i}); int extra = r() % 4; while (extra--) { int a = r() % n + 1, b = r() % n + 1; if (a != b) e.insert({std::min(a, b), std::max(a, b)}); } int k = r() % (n - 1) + 2; std::vector<int> sp(n); std::iota(sp.begin(), sp.end(), 1); std::shuffle(sp.begin(), sp.end(), r); sp.resize(k); printf("%d %d %d\n", n, (int)e.size(), k); for (int x : sp) printf("%d ", x); puts(""); for (auto [a, b] : e) printf("%d %d\n", a, b); }
